/* Focus story: consequences, visible memory, and a quiet editorial scene. */
const storyMemories=[
 ['Мама впервые услышала просьбу выслушать.','Разговор о письме остался незавершённым.','После резкой границы между вами появилась пауза.'],
 ['Папа помогает составить план поездки.','Папа согласился дать время на размышление.','Папа думает, что поездки не будет.'],
 ['Ника знает, что тебя радует в предложении.','Ника услышала, как важно сохранить связь с мамой.','Ника знает, что сегодня тебе нужна передышка.'],
 ['Вы с мамой назначили время для разговора.','Маме непросто, но вы нашли дату для разговора.','Звонок остался без ответа; тему можно поднять позже.'],
 ['Ты обсуждаешь с папой план на своих условиях.','Папа услышал просьбу говорить о другом.','Папа считает, что вопрос с поездкой закрыт.'],
 ['Ты уточняешь условия работы, прежде чем решать.','Ты просишь родителей просто выслушать.','Ты проводишь день без обсуждения решения.'],
 ['Ты едешь посмотреть новый город без обещания переезда.','Ты принимаешь предложение и готовишь переезд.','Ты остаёшься ради собственного проекта.'],
 ['Вы договариваетесь о новом ритме связи.','Вы оставляете место для разговора позже.','Ты выбираешь паузу и вернёшься к сообщению, когда появятся силы.']
];
function storyMemory(i){let decision=story.decisions?.[i];return Number.isInteger(decision)?storyMemories[i]?.[decision]:null}
// Keep the flagship in view; preserve other story sketches as an optional shelf.
let gamesHub=document.querySelector('#gamesHub');let gamesGrid=document.querySelector('#gameGrid');if(gamesHub&&gamesGrid){let shelf=document.createElement('details');shelf.className='master-other-stories';let summary=document.createElement('summary');summary.textContent='Другие сюжетные направления · 12 коротких историй';let oldHeading=gamesGrid.previousElementSibling;if(oldHeading&&oldHeading.tagName==='H2')oldHeading.remove();gamesGrid.before(shelf);shelf.append(summary,gamesGrid);let note=gamesHub.querySelector('.game-note');if(note){note.textContent='Это короткие прототипы. Образцовая история для оценки — «Тихий город».';shelf.append(note)}}
function bondLabel(n){return n>=67?'Теплее и открытее':n>=42?'Связь меняется':'Есть напряжение'}
function agencyLabel(n){return n>=67?'Решение звучит ясно':n>=42?'Ты ищешь свой голос':'Ты пока прислушиваешься к другим'}
function storyContext(){let c=story.chapter,d=story.decisions||[];if(c===1)return d[0]===2?'Утром вы с мамой расстались на напряжённой ноте. Папа слышал часть разговора.':d[0]===1?'Письмо осталось в кармане. Папа заметил, что ты о чём-то думаешь.':'Утром мама согласилась выслушать тебя. Это ещё не согласие с решением, но начало разговора.';
if(c===2)return d[1]===0?'Папа достал блокнот с вопросами о поездке. Тебе хочется поделиться этим с Никой.':d[1]===2?'Папа думает, что вопрос закрыт. Но вопрос для тебя ещё открыт.':'Папа дал тебе время. В кафе впервые можно спросить себя, чего хочешь ты.';
if(c===3)return d[0]===2?'После резкого разговора маме труднее начать первой. Телефон всё-таки звонит.':d[2]===0?'Слова Ники о твоём желании ещё звучат в голове. Звонит мама.':'Разговор с Никой помог сделать паузу. Теперь звонит мама.';
if(c===4)return d[3]===0?'После звонка мама рассказала папе о вашем плане поговорить.':d[3]===2?'Звонок мамы остался без ответа. Папа старается говорить осторожно.':'Вы с мамой ещё не договорили. Ужин с папой начинается с неловкой тишины.';
if(c===5)return d[4]===2?'Папа успокоился, услышав отказ от поездки, но эти слова не отражают всего, что ты чувствуешь.':d[4]===0?'Папин блокнот помог увидеть практические вопросы. Ника спросит о твоих желаниях.':'У вас с папой появилась пауза. На прогулке с Никой можно снова подумать о выборе.';
if(c===6)return d[5]===0?'Условия работы стали яснее. Теперь решение опирается на факты.':d[5]===1?'Родители знают, что тебе важно, чтобы они тебя выслушали. У вокзала это станет особенно важно.':'День тишины закончился. У тебя всё ещё есть право выбрать свой маршрут.';
if(c===7)return story.route==='move'?'После переезда связь с домом стала другой. Мама пишет первой.':story.route==='stay'?'Ты живёшь в своём городе и работаешь над новым проектом. Мама приглашает на обед.':'Ознакомительная поездка закончилась. Мама хочет знать, как всё прошло.';return ''}
function storyLine(scene){let c=story.chapter,d=story.decisions||[];if(c===1&&d[0]===2)return 'Папа: «Мама расстроена. Я не хочу решать за тебя. Просто скажи, что тебе сейчас нужно». ';if(c===2&&d[1]===0)return 'Ника: «Здорово, что вы с папой обсуждали план. А что из этого решения важно лично тебе?»';if(c===3&&d[0]===2)return 'Мама: «Мне было больно от нашего разговора. Но я не хочу, чтобы мы перестали говорить». ';if(c===4&&d[1]===2)return 'Папа: «Я услышал, что ты не поедешь. Это твоё решение или ты хочешь меня успокоить?»';if(c===6&&d[5]===0)return 'Мама: «Теперь у тебя есть условия работы. Я всё ещё переживаю, но хочу услышать твоё решение». ';return typeof scene.line==='function'?scene.line(story):scene.line}
relationCard=function(){let side=document.createElement('aside');side.className='story-side master-side';let card=document.createElement('div');card.className='card master-relations';let title=document.createElement('h3');title.textContent='Связи в истории';card.append(title);[['Мама',story.mom,bondLabel(story.mom)],['Папа',story.dad,bondLabel(story.dad)],['Собственный выбор',story.agency,agencyLabel(story.agency)]].forEach(([name,value,label])=>{let row=document.createElement('div');row.className='master-relation';let top=document.createElement('div');let strong=document.createElement('strong');strong.textContent=name;let status=document.createElement('small');status.textContent=label;top.append(strong,status);let rail=document.createElement('div');rail.className='master-rail';let fill=document.createElement('i');fill.style.width=value+'%';rail.append(fill);row.append(top,rail);card.append(row)});let hint=document.createElement('p');hint.textContent='Это изменения в сюжете, а не оценка твоих отношений в жизни.';hint.className='master-hint';card.append(hint);side.append(card);let memory=document.createElement('div');memory.className='card master-memory';let h=document.createElement('h3');h.textContent='История помнит';memory.append(h);let list=document.createElement('ol');let items=(story.decisions||[]).map((_,i)=>storyMemory(i)).filter(Boolean).slice(-3);if(items.length)items.forEach(x=>{let li=document.createElement('li');li.textContent=x;list.append(li)});else{let li=document.createElement('li');li.textContent='Первый выбор ещё впереди.';list.append(li)}memory.append(list);side.append(memory);return side};
renderScene=function(){if(!story)return showIntro();if(story.phase==='ending')return showEnding();let scene=storyScenes[story.chapter],root=gameFrame();root.classList.add('master-game');let heading=document.createElement('header');heading.className='master-heading';let tag=document.createElement('span');tag.textContent=`ГЛАВА ${story.chapter+1} / 8 · ${scene.time.toUpperCase()}`;let h=document.createElement('h2');h.textContent=scene.title;let place=document.createElement('p');place.textContent=scene.place+' · Тихий город';heading.append(tag,h,place);root.append(heading);let track=document.createElement('div');track.className='master-track';for(let i=0;i<8;i++){let seg=document.createElement('i');if(i<=story.chapter)seg.classList.add('active');track.append(seg)}root.append(track);let shell=document.createElement('div');shell.className='story-shell master-shell';let main=document.createElement('div');main.className='story-main';let stage=document.createElement('div');stage.className='master-stage place-'+scene.bg.split(' ')[0];stage.style.setProperty('--scene-index',String(story.chapter));let veil=document.createElement('div');veil.className='master-stage-veil';let badge=document.createElement('span');badge.className='master-stage-label';badge.textContent=scene.place+' / '+scene.time;let people=document.createElement('div');people.className='master-people';let hero=document.createElement('div');hero.textContent=story.name;let other=document.createElement('div');other.textContent=scene.npc==='mom'?'Мама':scene.npc==='dad'?'Папа':'Ника';people.append(hero,other);veil.append(badge,people);stage.append(veil);main.append(stage);
let objects=document.createElement('div');objects.className='master-objects';scene.objects.forEach((o,i)=>{let b=document.createElement('button');b.className='master-object'+(story.seen.includes(i)?' inspected':'');b.innerHTML='<span class="object-symbol"></span><span class="object-label"></span><small></small>';b.querySelector('.object-symbol').textContent=o.icon;b.querySelector('.object-label').textContent=o.label;b.querySelector('small').textContent=story.seen.includes(i)?'Осмотрено':'Осмотреть';b.onclick=()=>{if(!story.seen.includes(i)){story.seen.push(i);if(!story.inventory.includes(o.label))story.inventory.push(o.label);persistStory()}renderScene();let info=document.querySelector('#objectInfo');if(info){info.textContent=o.detail;info.scrollIntoView({behavior:'smooth',block:'nearest'})}};objects.append(b)});main.append(objects);
let card=document.createElement('div');card.className='master-narrative';let context=storyContext();if(context){let earlier=document.createElement('p');earlier.className='master-earlier';earlier.textContent='РАНЕЕ · '+context;card.append(earlier)}let intro=document.createElement('p');intro.className='master-intro';intro.textContent=typeof scene.intro==='function'?scene.intro(story):scene.intro;card.append(intro);let dialogue=document.createElement('blockquote');let who=document.createElement('span');who.textContent=scene.npc==='mom'?'МАМА':scene.npc==='dad'?'ПАПА':'НИКА';let text=document.createElement('p');text.textContent=storyLine(scene).replace(/^(Мама|Папа|Ника):\s*/,'');dialogue.append(who,text);card.append(dialogue);let info=document.createElement('div');info.id='objectInfo';info.className='master-object-info';info.textContent=story.seen.length?'Ты можешь осмотреть второй предмет или сделать выбор.':'Найди детали в сцене: осмотри хотя бы один предмет, чтобы открыть выбор.';card.append(info);let prompt=document.createElement('h3');prompt.textContent='Что делает '+story.name+'?';card.append(prompt);if(story.phase==='reply'){let choice=scene.choices[story.decisions[story.chapter]];let result=document.createElement('div');result.className='master-result';let selected=document.createElement('span');selected.textContent='ТВОЙ ВЫБОР';let chosen=document.createElement('p');chosen.textContent=choice.text;let reply=document.createElement('blockquote');reply.textContent=choice.reply;result.append(selected,chosen,reply);let trace=document.createElement('div');trace.className='master-trace';trace.textContent=storyMemory(story.chapter)||'Этот момент останется частью истории.';result.append(trace);card.append(result);let next=document.createElement('button');next.className='master-next';next.textContent=story.chapter===7?'Увидеть свою концовку →':'Продолжить историю →';next.onclick=advance;card.append(next)}else{let actions=document.createElement('div');actions.className='master-choices';scene.choices.forEach((choice,i)=>{let b=document.createElement('button');b.disabled=!story.seen.length;b.innerHTML='<span></span><b>↗</b>';b.querySelector('span').textContent=choice.text;b.onclick=()=>choose(i);actions.append(b)});card.append(actions)}main.append(card);shell.append(main,relationCard());root.append(shell);let foot=document.createElement('p');foot.className='story-footnote';foot.textContent='Вымышленная история. Здесь нет оценки реальных отношений или обещания изменить их после прохождения.';root.append(foot)};
showEnding=function(){let root=gameFrame();root.classList.add('master-game');let wrap=document.createElement('div');wrap.className='master-finale';let intro=document.createElement('span');intro.className='focus-eyebrow';intro.textContent='ПОСЛЕ ПОСЛЕДНЕЙ ГЛАВЫ';let h=document.createElement('h2');h.textContent=story.route==='move'?'Новый адрес, та же связь':story.route==='stay'?'Остаться и выбрать себя':'Дорога, на которой можно подумать';let lead=document.createElement('p');lead.textContent=story.route==='move'?story.name+' переезжает. Первые дни неловкие и новые. Мама всё ещё скучает; папа присылает список полезных адресов. Отношения продолжаются на расстоянии.':story.route==='stay'?story.name+' остаётся в городе и начинает свой проект. Это собственное решение, поэтому разговоры о границах продолжаются и дома.':story.name+' возвращается из ознакомительной поездки с вопросами и фактами. Решение ещё впереди, и это не делает путь менее своим.';wrap.append(intro,h,lead);let bonds=document.createElement('div');bonds.className='master-finale-bonds';let mom=document.createElement('div');mom.innerHTML='<span>С МАМОЙ</span><p></p>';mom.querySelector('p').textContent=story.mom>=60?'Вы научились говорить о планах чуть спокойнее, сохранив место для несогласия.':'Между вами пока напряжение. Разговор можно продолжить позже без требования немедленного согласия.';let dad=document.createElement('div');dad.innerHTML='<span>С ПАПОЙ</span><p></p>';dad.querySelector('p').textContent=story.dad>=60?'Его тревога чаще превращается в практическую помощь.':'Папе ещё трудно не решать за тебя. Можно возвращаться к конкретным договорённостям.';bonds.append(mom,dad);wrap.append(bonds);let path=document.createElement('section');path.className='master-finale-path';let ph=document.createElement('h3');ph.textContent='Твоя история помнит';path.append(ph);let ul=document.createElement('ul');[0,1,2,3,4,5,6,7].map(storyMemory).filter(Boolean).forEach(x=>{let li=document.createElement('li');li.textContent=x;ul.append(li)});path.append(ul);wrap.append(path);let note=document.createElement('p');note.className='story-footnote';note.textContent='Это финал игрового сюжета. В реальной жизни самостоятельность и близость сложнее любых игровых выборов.';wrap.append(note);let actions=document.createElement('div');actions.className='master-finale-actions';let again=document.createElement('button');again.className='master-next';again.textContent='Пройти по-другому →';again.onclick=()=>{localStorage.removeItem(STORY_KEY);story=null;renderGameHub();showIntro()};let hub=document.createElement('button');hub.className='focus-back';hub.textContent='К другим историям';hub.onclick=showHub;actions.append(again,hub);wrap.append(actions);root.append(wrap)};
